mapper.select:
select t1.id,t1.dateTime,t1.content,t1.userId,t1.type,t1.userIp,t1.requestMethod,t1.result,t1.logMsg,t1.userAddress,t1.userBrowser,t1.userSystem,t1.requestUrl,t1.param,t1.old_data as oldData,t1.new_data as newData,t1.froms,t1.resultData, IFNULL(t2.userName,'未知用户') as userName
from log t1
left join user t2 on t1.userId = t2.id
where (t1.type = 0 or t1.type = 1)

    and t1.type=#{type,jdbcType=INTEGER}


    and t1.logMsg like CONCAT('%',#{logMsg,jdbcType=VARCHAR},'%')


    and t1.userId=#{userId,jdbcType=INTEGER}


    and t2.userName=#{userName,jdbcType=VARCHAR}


    and t1.dateTime between #{startTime} and #{endTime}


    and t1.result=#{result,jdbcType=VARCHAR}


    and t1.froms=#{froms,jdbcType=VARCHAR}

order by t1.dateTime desc

select t1.id,t1.dateTime,t1.content,t1.userId,t1.type,t1.userIp,t1.requestMethod,t1.result,t1.logMsg,t1.userAddress,t1.userBrowser,t1.userSystem,t1.requestUrl,t1.param,t1.old_data as oldData,t1.new_data as newData,t1.froms,t1.resultData, IFNULL(t2.userName,'未知用户') as userName
from log t1
left join user t2 on t1.userId = t2.id
where (t1.type <> 0 and t1.type <> 1)

    and t1.type=#{type,jdbcType=INTEGER}


    and t1.content like CONCAT('%',#{logMsg,jdbcType=VARCHAR},'%')


    and t1.userId=#{userId,jdbcType=INTEGER}


    and t2.userName=#{userName,jdbcType=VARCHAR}


    and t1.dateTime between #{startTime} and #{endTime}


    and t1.result=#{result,jdbcType=VARCHAR}


    and t1.froms=#{froms,jdbcType=VARCHAR}

order by t1.dateTime desc

mapper.delete:
delete from log
where id IN

    #{id}
